const glyphs={P:['11110','10001','10001','11110','10000','10000','10000'],O:['01110','10001','10001','10001','10001','10001','01110'],R:['11110','10001','10001','11110','10100','10010','10001'],T:['11111','00100','00100','00100','00100','00100','00100'],F:['11111','10000','10000','11110','10000','10000','10000'],L:['10000','10000','10000','10000','10000','10000','11111'],I:['00100','00100','00100','00100','00100','00100','00100']};
document.querySelectorAll('.pixel-word').forEach(el=>{el.innerHTML=[...el.textContent.trim()].map(c=>`<span class="pixel-letter" aria-hidden="true"><svg viewBox="0 0 5 7">${glyphs[c].map((row,y)=>[...row].map((v,x)=>v==='1'?`<rect x="${x}" y="${y}" width="1.02" height="1.02" rx=".12"/>`:'').join('')).join('')}</svg></span>`).join('')});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-open');observer.unobserve(entry.target)}}),{threshold:.2});document.querySelectorAll('.folder-stage,.reveal').forEach(el=>observer.observe(el));
const dialog=document.querySelector('#coming-dialog');document.querySelectorAll('.future').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelectorAll('.close-dialog,.close-action').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&matchMedia('(pointer:fine)').matches){document.querySelectorAll('[data-tilt]').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.transform=`perspective(1000px) rotateX(${-(e.clientY-r.top-r.height/2)/r.height*10}deg) rotateY(${(e.clientX-r.left-r.width/2)/r.width*14}deg)`});el.addEventListener('pointerleave',()=>el.style.transform='')})}
